package io.knowledgebrain.learning;
import java.io.IOException;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.*;
import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.MeterRegistry;

@RestController
@ConditionalOnProperty(name="brain.learning.api.enabled",havingValue="true")
@RequestMapping("/api/spaces/{spaceId}/roadmaps/{roadmapId}")
final class LearningStudyController {
 private final LearningStudyStore store;private final RoadmapController authority;private final MeterRegistry metrics;
 LearningStudyController(LearningStudyStore store,RoadmapController authority,MeterRegistry metrics){this.store=store;this.authority=authority;this.metrics=metrics;}
 static long version(HttpServletRequest r,String prefix,boolean zero){var values=Collections.list(r.getHeaders("If-Match"));if(values.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(values.size()!=1||!values.getFirst().matches("\""+prefix+(zero?"(0|[1-9][0-9]{0,18})":"[1-9][0-9]{0,18}")+"\""))throw LearningStudyStore.bad();try{return Long.parseLong(values.getFirst().substring(prefix.length()+1,values.getFirst().length()-1));}catch(NumberFormatException e){throw LearningStudyStore.bad();}}
 static String tag(String prefix,long version){return "\""+prefix+version+"\"";}
 private UUID authorize(String space,HttpServletRequest r,boolean write,String trace){return authority.authorize(RoadmapGraph.id(space),r,write,trace);}
 private static void query(HttpServletRequest r,Set<String> fields){RoadmapController.parameters(r,fields);}
 private static UUID id(String raw){return RoadmapGraph.id(raw);}
 private void count(String operation){metrics.counter("brain.learning.records","operation",operation).increment();}
 private String status(HttpServletRequest r)throws IOException{var value=authority.body(r,4096);if(value.size()!=1||!value.path("status").isString())throw LearningStudyStore.bad();return value.path("status").asString();}
 private LearningStudyStore.Input input(HttpServletRequest r)throws IOException{var value=authority.body(r,65536);if(value.size()!=4||!value.path("nodeId").isString()||!value.path("startedAt").isString()||!value.path("endedAt").isString()||!value.path("note").isString())throw LearningStudyStore.bad();return new LearningStudyStore.Input(id(value.path("nodeId").asString()),value.path("startedAt").asString(),value.path("endedAt").asString(),value.path("note").asString());}
 private String key(HttpServletRequest r){var keys=Collections.list(r.getHeaders("Idempotency-Key"));if(keys.size()!=1||!keys.getFirst().matches("[0-9a-f]{32}"))throw LearningStudyStore.bad();return keys.getFirst();}
 private static <T> ResponseEntity<T> read(T body){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(body);}
 private static ResponseEntity<LearningStudyStore.Progress> progress(LearningStudyStore.Progress p){return ResponseEntity.ok().eTag(tag("pr",p.version())).cacheControl(CacheControl.noStore()).body(p);}
 private static ResponseEntity<LearningStudyStore.Session> session(LearningStudyStore.Session s){return ResponseEntity.ok().eTag(tag("ss",s.version())).cacheControl(CacheControl.noStore()).body(s);}
 @GetMapping("/learning") ResponseEntity<LearningStudyStore.Summary> summary(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){query(r,Set.of());UUID roadmap=id(roadmapId);authorize(spaceId,r,false,RoadmapController.parent(r));count("summary");return read(store.summary(id(spaceId),roadmap));}
 @GetMapping("/nodes/{nodeId}/progress") ResponseEntity<LearningStudyStore.Progress> progress(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String nodeId,HttpServletRequest r){query(r,Set.of());UUID roadmap=id(roadmapId),node=id(nodeId);authorize(spaceId,r,false,RoadmapController.parent(r));count("progress-read");return progress(store.progress(id(spaceId),roadmap,node));}
 @PutMapping("/nodes/{nodeId}/progress") ResponseEntity<LearningStudyStore.Progress> writeProgress(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String nodeId,HttpServletRequest r)throws IOException{query(r,Set.of());UUID roadmap=id(roadmapId),node=id(nodeId);String trace=RoadmapController.parent(r);UUID actor=authorize(spaceId,r,true,trace);long version=version(r,"pr",true);String status=status(r);var value=store.progress(id(spaceId),roadmap,node,actor,version,status,trace.substring(3,35));count("progress-write");return progress(value);}
 @GetMapping("/nodes/{nodeId}/progress/revisions") ResponseEntity<List<LearningStudyStore.ProgressRevision>> progressHistory(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String nodeId,HttpServletRequest r){query(r,Set.of("before","limit"));UUID roadmap=id(roadmapId),node=id(nodeId);long before=RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)RoadmapController.number(r.getParameter("limit"),5,10);authorize(spaceId,r,false,RoadmapController.parent(r));count("progress-history");return read(store.progressHistory(id(spaceId),roadmap,node,before,limit));}
 @GetMapping("/study-sessions") ResponseEntity<LearningStudyStore.SessionPage> sessions(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){query(r,Set.of("after","limit"));UUID roadmap=id(roadmapId),after=r.getParameter("after")==null?null:id(r.getParameter("after"));int limit=(int)RoadmapController.number(r.getParameter("limit"),20,100);authorize(spaceId,r,false,RoadmapController.parent(r));count("session-catalog");return read(store.sessions(id(spaceId),roadmap,after,limit));}
 @PostMapping("/study-sessions") ResponseEntity<LearningStudyStore.Session> record(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r)throws IOException{query(r,Set.of());UUID roadmap=id(roadmapId);String trace=RoadmapController.parent(r);UUID actor=authorize(spaceId,r,true,trace);String key=key(r);var input=input(r);var result=store.record(id(spaceId),roadmap,actor,key,input,trace.substring(3,35));count(result.created()?"session-created":"session-replayed");return ResponseEntity.status(result.created()?201:200).header("Location","/api/spaces/"+spaceId+"/roadmaps/"+roadmap+"/study-sessions/"+result.session().sessionId()).eTag(tag("ss",result.session().version())).cacheControl(CacheControl.noStore()).body(result.session());}
 @GetMapping("/study-sessions/{sessionId}") ResponseEntity<LearningStudyStore.Session> session(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String sessionId,HttpServletRequest r){query(r,Set.of());UUID roadmap=id(roadmapId),session=id(sessionId);authorize(spaceId,r,false,RoadmapController.parent(r));count("session-read");return session(store.session(id(spaceId),roadmap,session));}
 @PutMapping("/study-sessions/{sessionId}") ResponseEntity<LearningStudyStore.Session> edit(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String sessionId,HttpServletRequest r)throws IOException{query(r,Set.of());UUID roadmap=id(roadmapId),session=id(sessionId);String trace=RoadmapController.parent(r);UUID actor=authorize(spaceId,r,true,trace);long version=version(r,"ss",false);var input=input(r);var value=store.changeSession(id(spaceId),roadmap,session,actor,version,input,false,trace.substring(3,35));count("session-edit");return session(value);}
 @DeleteMapping("/study-sessions/{sessionId}") ResponseEntity<Void> retire(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String sessionId,HttpServletRequest r){query(r,Set.of());if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw LearningStudyStore.bad();UUID roadmap=id(roadmapId),session=id(sessionId);String trace=RoadmapController.parent(r);UUID actor=authorize(spaceId,r,true,trace);var value=store.changeSession(id(spaceId),roadmap,session,actor,version(r,"ss",false),null,true,trace.substring(3,35));count("session-retired");return ResponseEntity.noContent().eTag(tag("ss",value.version())).cacheControl(CacheControl.noStore()).build();}
 @GetMapping("/study-sessions/{sessionId}/revisions") ResponseEntity<List<LearningStudyStore.SessionRevision>> sessionHistory(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String sessionId,HttpServletRequest r){query(r,Set.of("before","limit"));UUID roadmap=id(roadmapId),session=id(sessionId);long before=RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)RoadmapController.number(r.getParameter("limit"),5,10);authorize(spaceId,r,false,RoadmapController.parent(r));count("session-history");return read(store.sessionHistory(id(spaceId),roadmap,session,before,limit));}
}
